const $ = id => document.getElementById(id);
const uniq = i => [...new Set(ROWS.map(r => r[i]))].sort((a, b) => a.localeCompare(b, "ko"));
const MONTHS = [...new Set(ROWS.map(r => r[1].slice(0, 7)))].sort();
const STATES = ["완료", "진행중", "반려"];

function fill(sel, items, allLabel) {
  sel.innerHTML = (allLabel ? `<option value="">${allLabel}</option>` : "") +
    items.map(v => `<option value="${v}">${v}</option>`).join("");
}
fill($("fSido"), uniq(2), "전체");
fill($("fDept"), uniq(4), "전체");
fill($("fCh"), uniq(6), "전체");
fill($("fSt"), STATES, "전체");
fill($("fFrom"), MONTHS); fill($("fTo"), MONTHS);
$("fTo").value = MONTHS[MONTHS.length - 1];

function filtered() {
  const s = $("fSido").value, d = $("fDept").value, c = $("fCh").value, st = $("fSt").value;
  let a = $("fFrom").value, b = $("fTo").value; if (a > b) [a, b] = [b, a];
  const q = $("fQ").value.trim();
  return ROWS.filter(r => (!s || r[2] === s) && (!d || r[4] === d) && (!c || r[6] === c) && (!st || r[7] === st)
    && r[1].slice(0, 7) >= a && r[1].slice(0, 7) <= b && (!q || r[0].includes(q) || r[5].includes(q)));
}

const tok = n => getComputedStyle(document.documentElement).getPropertyValue(n).trim();
const fmt = (x, d = 0) => x.toLocaleString("ko-KR", { minimumFractionDigits: d, maximumFractionDigits: d });
let charts = {};

function baseOpts(extra = {}) {
  const fg = tok("--muted"), line = tok("--line");
  return Object.assign({
    responsive: true, maintainAspectRatio: false, animation: false,
    plugins: { legend: { labels: { color: fg, boxWidth: 12, font: { family: tok("--font") } } },
               tooltip: { titleFont: { family: tok("--font") }, bodyFont: { family: tok("--font") } } },
    scales: { x: { ticks: { color: fg }, grid: { color: line } }, y: { ticks: { color: fg }, grid: { color: line }, beginAtZero: true } }
  }, extra);
}

function draw(rows) {
  Object.values(charts).forEach(c => c.destroy());
  const ok = tok("--ok"), warn = tok("--warn"), bad = tok("--bad"), acc = tok("--accent"), soft = tok("--accent-soft");

  // 월별 × 상태
  const mLabels = MONTHS.map(m => +m.slice(5) + "월");
  const stColor = { 완료: ok, 진행중: warn, 반려: bad };
  charts.m = new Chart($("cMonth"), { type: "bar",
    data: { labels: mLabels, datasets: STATES.map(st => ({ label: st, backgroundColor: stColor[st],
      data: MONTHS.map(m => rows.filter(r => r[1].startsWith(m) && r[7] === st).length) })) },
    options: baseOpts({ scales: { x: { stacked: true, ticks: { color: tok("--muted") }, grid: { display: false } },
                                  y: { stacked: true, beginAtZero: true, ticks: { color: tok("--muted"), precision: 0 }, grid: { color: tok("--line") } } } }) });

  // 부서별
  const dc = {}; rows.forEach(r => dc[r[4]] = (dc[r[4]] || 0) + 1);
  const ds = Object.entries(dc).sort((a, b) => b[1] - a[1]);
  charts.d = new Chart($("cDept"), { type: "bar",
    data: { labels: ds.map(x => x[0]), datasets: [{ label: "건수", data: ds.map(x => x[1]), backgroundColor: acc }] },
    options: baseOpts({ indexAxis: "y", plugins: { legend: { display: false } },
      scales: { x: { beginAtZero: true, ticks: { color: tok("--muted"), precision: 0 }, grid: { color: tok("--line") } },
                y: { ticks: { color: tok("--muted") }, grid: { display: false } } } }) });

  // 접수경로별 만족도
  const chs = uniq(6);
  const sat = chs.map(c => { const v = rows.filter(r => r[6] === c && r[9] != null).map(r => r[9]);
    return v.length ? +(v.reduce((a, b) => a + b, 0) / v.length).toFixed(2) : null; });
  charts.c = new Chart($("cCh"), { type: "bar",
    data: { labels: chs, datasets: [{ label: "평균 만족도", data: sat, backgroundColor: soft, borderColor: acc, borderWidth: 1.5 }] },
    options: baseOpts({ plugins: { legend: { display: false } },
      scales: { x: { ticks: { color: tok("--muted") }, grid: { display: false } },
                y: { min: 0, max: 5, ticks: { color: tok("--muted"), stepSize: 1 }, grid: { color: tok("--line") } } } }) });

  // 처리일수 분포 1~14
  const days = Array.from({ length: 14 }, (_, i) => i + 1);
  charts.h = new Chart($("cDays"), { type: "bar",
    data: { labels: days.map(d => d + "일"), datasets: [{ label: "건수", data: days.map(d => rows.filter(r => r[8] === d).length),
      backgroundColor: days.map(d => d > 7 ? bad : acc) }] },
    options: baseOpts({ plugins: { legend: { display: false } },
      scales: { x: { ticks: { color: tok("--muted") }, grid: { display: false } },
                y: { beginAtZero: true, ticks: { color: tok("--muted"), precision: 0 }, grid: { color: tok("--line") } } } }) });
}

function render() {
  const rows = filtered();
  const n = rows.length, done = rows.filter(r => r[7] === "완료").length;
  const dv = rows.filter(r => r[8] != null).map(r => r[8]);
  const sv = rows.filter(r => r[9] != null).map(r => r[9]);
  const avg = a => a.length ? a.reduce((x, y) => x + y, 0) / a.length : null;
  $("kCount").innerHTML = `${fmt(n)}<small>건</small>`;
  $("kDone").innerHTML = n ? `${fmt(done / n * 100, 1)}<small>%</small>` : "-";
  $("kDays").innerHTML = dv.length ? `${fmt(avg(dv), 2)}<small>일</small>` : "-";
  $("kLate").innerHTML = `${fmt(dv.filter(d => d > 7).length)}<small>건</small>`;
  $("kSat").innerHTML = sv.length ? `${fmt(avg(sv), 2)}<small>점</small>` : "-";

  if (typeof Chart !== "undefined") draw(rows);

  const shown = [...rows].sort((a, b) => b[1].localeCompare(a[1]) || b[0].localeCompare(a[0])).slice(0, 100);
  $("tTitle").textContent = n > 100 ? `상세 목록 · 최근 100건 (전체 ${fmt(n)}건)` : `상세 목록 · ${fmt(n)}건`;
  $("tBody").innerHTML = shown.length ? shown.map(r => `<tr><td>${r[0]}</td><td>${r[1]}</td><td>${r[2]}</td><td>${r[3]}</td><td>${r[4]}</td><td>${r[5]}</td><td>${r[6]}</td>
    <td><span class="pill p-${r[7]}">${r[7]}</span></td>
    <td class="n${r[8] > 7 ? " late" : ""}">${r[8] ?? "–"}</td><td class="n">${r[9] ?? "–"}</td></tr>`).join("")
    : `<tr><td colspan="10" class="empty">조건에 맞는 민원이 없습니다. 필터를 넓혀 보세요.</td></tr>`;
}

["fSido", "fDept", "fCh", "fSt", "fFrom", "fTo"].forEach(id => $(id).addEventListener("change", render));
$("fQ").addEventListener("input", render);
$("reset").addEventListener("click", () => {
  ["fSido", "fDept", "fCh", "fSt", "fQ"].forEach(id => $(id).value = "");
  $("fFrom").value = MONTHS[0]; $("fTo").value = MONTHS[MONTHS.length - 1]; render();
});
matchMedia("(prefers-color-scheme: dark)").addEventListener("change", render);
new MutationObserver(render).observe(document.documentElement, { attributes: true, attributeFilter: ["data-theme"] });
render();
